import json
from collections import Counter

with open('/home/ubuntu/.claude-account-2/projects/-home-ubuntu--agent-ml-research-idea-gen-0509-13-projects-contamcal-irt-calibration--claude-sessions-agent-c876925a/26192e2f-428a-4b04-a898-73702e5a3ab3/tool-results/mcp-agent-ml-research-read_registry-1778942127696.txt', 'r') as f:
    outer = json.load(f)

inner = json.loads(outer['result'])
experiments = inner['data']['experiments']

status_counts = Counter()
running = []
preparing = []

for exp_id, exp in experiments.items():
    status = exp.get('status', 'UNKNOWN')
    status_counts[status] += 1

    if status == 'RUNNING':
        spec = exp.get('spec', {}) or {}
        running.append({
            'exp_id': exp_id,
            'hypothesis': exp.get('hypothesis', 'N/A'),
            'server': spec.get('server', exp.get('server', 'N/A')),
            'gpu': spec.get('gpu', exp.get('gpu', 'N/A')),
            'pid': spec.get('pid', exp.get('pid', 'N/A')),
        })
    elif status == 'PREPARING':
        preparing.append({
            'exp_id': exp_id,
            'hypothesis': exp.get('hypothesis', 'N/A'),
        })

print('=== RUNNING experiments ===')
if running:
    for r in running:
        print(f\"  {r['exp_id']}\")
        print(f\"    hypothesis: {r['hypothesis']}\")
        print(f\"    server: {r['server']}, gpu: {r['gpu']}, pid: {r['pid']}\")
else:
    print('  (none)')

print()
print('=== PREPARING experiments ===')
if preparing:
    for p in preparing:
        print(f\"  {p['exp_id']}\")
        print(f\"    hypothesis: {p['hypothesis']}\")
else:
    print('  (none)')

print()
print('=== Status counts ===')
for status, count in sorted(status_counts.items(), key=lambda x: -x[1]):
    print(f'  {status}: {count}')
print(f'  TOTAL: {sum(status_counts.values())}')
